={{ (() => {
  const input = $('Merge Create/Update').item.json;
  const prompts = $('Templates').first().json.prompt || {};
  const templateKey = input.template || 'general';
  const templateInstruction = prompts[templateKey] || prompts.general || 'Write a general Confluence page that presents the available information clearly. Use Confluence storage-format HTML.';
  let text = 'You are a technical writer creating a Confluence page.\n\n';
  text += 'Mode: ' + input.mode + '\n';
  text += 'Template instruction: ' + templateInstruction + '\n';
  text += 'Additional instructions: ' + (input.instructions || 'none') + '\n\n';
  if (input.existingBody) text += '\nExisting page body (update this, do not rewrite from scratch):\n' + input.existingBody;
  text += '\n\nSource data:\n' + input.sourceText + '\n\n';
  text += 'Generate a complete Confluence storage-format HTML body. Output only the HTML.';
  return text;
})() }}

