={{ (() => {
  const input = $('Normalize Input1').first().json;
  const typeGuidance = {
    'Major release': 'Emphasize the What\'s New section with multiple detailed feature entries. TL;DR should convey scope and impact. Include action_required if any migration or setup step is needed.',
    'Minor release': 'Use a small number of What\'s New entries and/or Improvements. Keep it concise — this is not a major event.',
    'Process update': 'Emphasize the Steps section explaining the new process clearly and sequentially. TL;DR should state what is changing and why. Use action_required for any compliance deadline.',
    'Maintenance': 'Emphasize TL;DR (what is happening, when, expected impact) and action_required (what the reader should do or expect). Keep What\'s New empty or minimal.',
    'Defect': 'Emphasize the Fixes section. TL;DR should explain what was broken and its impact. Keep What\'s New and Improvements empty unless directly relevant.'
  };
  const guidance = typeGuidance[input.announcementType] || 'Use whichever sections genuinely fit the content — do not force empty sections to have content.';
  let text = 'You are writing content for a MarTech team announcement page.\n\n';
  text += 'Announcement type: ' + (input.announcementType || 'unspecified') + '\n';
  text += 'Type-specific guidance: ' + guidance + '\n';
  text += 'Product: ' + (input.product || 'none — this is a general MarTech announcement, do not invent a product name') + '\n';
  text += 'Additional instructions: ' + (input.instructions || 'none') + '\n\n';
  text += 'Source content:\n' + input.content + '\n\n';
  text += 'Return ONLY a JSON object (no markdown fences, no prose outside the JSON) with this exact shape:\n';
  text += '{ "title": string, "tldr_short": string (one sentence), "tldr": string (full paragraph), "version": string or null, "status_label": string or null, "date": string or null, "whats_new": [ { "title": string, "description": string } ] or [], "steps": [ { "title": string, "description": string } ] or [], "improvements": [string] or [], "fixes": [string] or [], "action_required": string or null, "related_link": string or null }';
  text += '\n\nOnly populate the arrays/fields that make sense for this announcement type and content — leave others as empty arrays or null rather than forcing filler content.';
  return text;
})() }}

