let raw = ($json.output || '').trim();
// Strip markdown code fences if present — the model is instructed not to
// use them, but sometimes does anyway; parse defensively rather than
// trust the instruction alone.
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();

let ai;
try {
  ai = JSON.parse(raw);
} catch (e) {
  throw new Error('Announcement generation did not return valid JSON: ' + raw);
}

function esc(str) {
  return String(str ?? '')
    // Normalize non-breaking spaces (U+00A0) to plain spaces first —
    // these commonly slip in from pasted Word/rich-text content and can
    // interfere with downstream rendering in ways a plain space doesn't.
    .replace(/\u00A0/g, ' ')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const whatsNewHtml = (ai.whats_new || []).map(function (f) {
  return '<div class="mtrn-feature">'
    + '<div class="mtrn-feature-icon">+</div>'
    + '<div class="mtrn-feature-title">' + esc(f.title) + '</div>'
    + '<p class="mtrn-feature-desc">' + esc(f.description) + '</p>'
    + '</div>';
}).join('');
const whatsNewSection = whatsNewHtml
  ? '<div class="mtrn-section"><div class="mtrn-section-title"><span class="mtrn-dot mtrn-dot-new"></span>What\'s New</div>' + whatsNewHtml + '</div>'
  : '';

const stepsHtml = (ai.steps || []).map(function (s) {
  return '<li><strong>' + esc(s.title) + '</strong>' + (s.description ? ' \u2014 ' + esc(s.description) : '') + '</li>';
}).join('');
const stepsSection = stepsHtml
  ? '<div class="mtrn-section"><div class="mtrn-section-title">Steps</div><ol class="mtrn-highlights">' + stepsHtml + '</ol></div>'
  : '';

const improvementsHtml = (ai.improvements || []).map(function (i) {
  return '<div class="mtrn-list-item"><span class="mtrn-list-mark mtrn-list-mark-improve">&uarr;</span>' + esc(i) + '</div>';
}).join('');
const improvementsSection = improvementsHtml
  ? '<div class="mtrn-section"><div class="mtrn-section-title"><span class="mtrn-dot mtrn-dot-improve"></span>Improvements</div>' + improvementsHtml + '</div>'
  : '';

const fixesHtml = (ai.fixes || []).map(function (fx) {
  return '<div class="mtrn-list-item"><span class="mtrn-list-mark mtrn-list-mark-fix">&check;</span>' + esc(fx) + '</div>';
}).join('');
const fixesSection = fixesHtml
  ? '<div class="mtrn-section"><div class="mtrn-section-title"><span class="mtrn-dot mtrn-dot-fix"></span>Fixes</div>' + fixesHtml + '</div>'
  : '';

const calloutHtml = ai.action_required
  ? '<div class="mtrn-callout"><div class="mtrn-callout-title">Action Required</div><p class="mtrn-callout-body">' + esc(ai.action_required) + '</p></div>'
  : '';

const versionBadge = ai.version ? '<span class="mtrn-badge mtrn-badge-version">' + esc(ai.version) + '</span>' : '';
const statusBadge = ai.status_label ? '<span class="mtrn-badge mtrn-badge-live">' + esc(ai.status_label) + '</span>' : '';
const dateBadge = ai.date ? '<span class="mtrn-badge mtrn-badge-date">' + esc(ai.date) + '</span>' : '';

const styleBlock = `<style>
  .mtrn-embed {
    --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Helvetica Neue", Arial, sans-serif;
