      radial-gradient(ellipse 70% 60% at 15% -10%, rgba(61,139,255,0.16), transparent 65%),
      radial-gradient(ellipse 50% 50% at 100% 10%, rgba(36,217,199,0.10), transparent 60%),
      var(--bg-void);
    border-bottom: 1px solid var(--glass-border);
  }
  .mtrn-banner-top {
    display: flex; align-items: center; gap: 14px; margin-bottom: 18px; flex-wrap: wrap;
  }
  .mtrn-wordmark {
    display: flex; align-items: center; gap: 8px;
    font-family: var(--font-mono); font-weight: 700 !important; font-size: 13px;
