  /* ===== Body ===== */
  .mtrn-body { padding: 32px 36px 40px; }

  .mtrn-meta-row { margin-bottom: 30px; }
  .mtrn-badge {
    display: inline-block;
    font-family: var(--font-mono); font-size: 11px; letter-spacing: 0.04em;
