  }
  .mtrn-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; margin-right: 8px; position: relative; top: -1px; }
  .mtrn-dot-new { background: var(--accent); box-shadow: 0 0 6px var(--accent); }
