  .mtrn-footer-author { font-size: 12px; color: var(--text-faint); font-family: var(--font-mono); }
</style>`;

const html = '<div class="mtrn-embed">'
  + styleBlock
  + '<div class="mtrn-banner">'
    + '<div class="mtrn-banner-top">'
      + '<div class="mtrn-wordmark"><span class="mtrn-wordmark-dot"></span>MARTECH</div>'
      + '<div class="mtrn-eyebrow">Release Notes</div>'
    + '</div>'
    + '<h1 class="mtrn-title">' + esc(ai.title || 'Announcement') + '</h1>'
    + '<p class="mtrn-subtitle">' + esc(ai.tldr_short || '') + '</p>'
  + '</div>'
  + '<div class="mtrn-body">'
    + '<div class="mtrn-meta-row">' + versionBadge + statusBadge + dateBadge + '</div>'
    + '<div class="mtrn-panel"><div class="mtrn-panel-label">TL;DR</div><p class="mtrn-panel-body">' + esc(ai.tldr || '') + '</p></div>'
    + whatsNewSection
    + stepsSection
    + improvementsSection
    + fixesSection
    + calloutHtml
    + '<div class="mtrn-footer"><div class="mtrn-footer-links"><a href="' + esc(ai.related_link || '#') + '">Related ticket</a></div><div class="mtrn-footer-author">Posted by MarTech</div></div>'
  + '</div>'
  + '</div>';

const cdataSafe = html.replace(/\]\]>/g, ']]]]><![CDATA[>');
const macroWrapped = '<ac:structured-macro ac:name="html" ac:schema-version="1"><ac:plain-text-body><![CDATA[' + cdataSafe + ']]></ac:plain-text-body></ac:structured-macro>';

return [{
  json: {
    title: $('Normalize Input1').first().json.title,
    spaceKey: $('Normalize Input1').first().json.spaceKey,
    announcementName: $('Normalize Input1').first().json.announcementName,
    erpnextBaseUrl: $('Normalize Input1').first().json.erpnextBaseUrl,
    mattermostChannelId: $('Normalize Input1').first().json.mattermostChannelId,
    confluenceBaseUrl: $('Normalize Input1').first().json.confluenceBaseUrl,
    body: macroWrapped
  }
}];
